BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" SERIAL PRIMARY KEY, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" SERIAL PRIMARY KEY, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);

-- Создаем таблицу auth_group
CREATE TABLE IF NOT EXISTS "auth_group" (
    "id" SERIAL PRIMARY KEY,
    "name" varchar(150) NOT NULL UNIQUE
);

-- Создаем таблицу auth_permission
CREATE TABLE IF NOT EXISTS "auth_permission" (
    "id" SERIAL PRIMARY KEY,
    "name" varchar(255) NOT NULL,
    "content_type_id" integer NOT NULL,
    "codename" varchar(100) NOT NULL
);

-- Создаем таблицу auth_group_permissions
CREATE TABLE IF NOT EXISTS "auth_group_permissions" (
    "id" SERIAL PRIMARY KEY,
    "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED,
    "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" SERIAL PRIMARY KEY, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" SERIAL PRIMARY KEY, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" SERIAL PRIMARY KEY, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "printery_order_owner" ("id" SERIAL PRIMARY KEY, "order_id" bigint NOT NULL REFERENCES "printery_order" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "printery_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "printery_paper_manufacturer" ("id" SERIAL PRIMARY KEY, "paper_id" bigint NOT NULL REFERENCES "printery_paper" ("id") DEFERRABLE INITIALLY DEFERRED, "company_id" bigint NOT NULL REFERENCES "printery_company" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "printery_user_groups" ("id" SERIAL PRIMARY KEY, "user_id" bigint NOT NULL REFERENCES "printery_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "printery_user_user_permissions" ("id" SERIAL PRIMARY KEY, "user_id" bigint NOT NULL REFERENCES "printery_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" SERIAL PRIMARY KEY, "action_time" timestamp NOT NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "printery_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0));
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS "printery_company" ("id" SERIAL PRIMARY KEY, "address" varchar(64) NOT NULL, "city" varchar(25) NOT NULL, "postal_code" integer NULL, "country" varchar(56) NOT NULL, "email" varchar(64) NOT NULL, "phone" varchar(128) NOT NULL, "is_manufacturer" bool NOT NULL, "is_customer" bool NOT NULL, "name" varchar(64) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "printery_user" ("id" SERIAL PRIMARY KEY, "password" varchar(128) NOT NULL, "last_login" timestamp NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" timestamp NOT NULL, "is_customer" bool NOT NULL, "is_employee" bool NOT NULL, "company_id" bigint NULL REFERENCES "printery_company" ("id") DEFERRABLE INITIALLY DEFERRED, "phone_number" varchar(128) NOT NULL);
CREATE TABLE IF NOT EXISTS "authtoken_token" ("key" varchar(40) NOT NULL PRIMARY KEY, "created" timestamp NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "printery_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "token_blacklist_blacklistedtoken" ("blacklisted_at" timestamp NOT NULL, "token_id" bigint NOT NULL UNIQUE REFERENCES "token_blacklist_outstandingtoken" ("id") DEFERRABLE INITIALLY DEFERRED, "id" SERIAL PRIMARY KEY);
CREATE TABLE IF NOT EXISTS "token_blacklist_outstandingtoken" ("token" text NOT NULL, "created_at" timestamp NULL, "expires_at" timestamp NOT NULL, "user_id" bigint NULL REFERENCES "printery_user" ("id") DEFERRABLE INITIALLY DEFERRED, "jti" varchar(255) NOT NULL UNIQUE, "id" SERIAL PRIMARY KEY);
CREATE TABLE IF NOT EXISTS "printery_order" ("id" SERIAL PRIMARY KEY, "number" integer NOT NULL UNIQUE, "name" varchar(16) NOT NULL, "circulation" integer NULL, "binding" varchar(4) NOT NULL, "width" integer NULL, "height" integer NULL, "created" timestamp NOT NULL, "due_date" timestamp NULL, "delivery_date" timestamp NULL, "submiting_files" timestamp NULL, "type" varchar(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "printery_part" ("id" SERIAL PRIMARY KEY, "part_name" varchar(3) NOT NULL, "pages" integer NULL, "color" varchar(3) NOT NULL, "laminate" varchar(3) NOT NULL, "uflak" bool NOT NULL, "order_id" bigint NOT NULL REFERENCES "printery_order" ("id") DEFERRABLE INITIALLY DEFERRED, "paper_id" bigint NULL REFERENCES "printery_paper" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "printery_paper" ("id" SERIAL PRIMARY KEY, "name" varchar(64) NOT NULL, "type" varchar(3) NOT NULL, "width" integer NULL, "height" integer NULL, "density" integer NULL);
CREATE TABLE IF NOT EXISTS "printery_printschedule" ("id" SERIAL PRIMARY KEY, "parent_day" varchar(20) NOT NULL, "position" integer NULL, "sm1" bool NOT NULL, "rapida" bool NOT NULL, "sm2" bool NOT NULL, "order_part_id" bigint NOT NULL REFERENCES "printery_part" ("id") DEFERRABLE INITIALLY DEFERRED, "circulation_sheets" integer NULL, "printed_sheets" real NULL, "ctp_id" bigint NULL REFERENCES "printery_ctp" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "printery_ctp" ("id" SERIAL PRIMARY KEY, "plates" integer NULL, "plates_bad" integer NULL, "plates_done_date" timestamp NULL, "notes" text NOT NULL, "printing_id" bigint NULL REFERENCES "printery_printschedule" ("id") DEFERRABLE INITIALLY DEFERRED, "status" varchar(15) NULL);
